#include <type_traits>
#include <iostream>
struct Trivial {
    int x;  // Only trivial members; no user-defined functions
};
struct NonTrivial {
    int x;
    NonTrivial() {}  // User-defined constructor makes it non-trivial
};
int main() {
    if (std::is_trivial<Trivial>::value) {
        std::cout << "Trivial is trivial and can be optimized." << std::endl;
    }
    if (!std::is_trivial<NonTrivial>::value) {
        std::cout << "NonTrivial is not trivial due to user-defined constructor." << std::endl;
    }
    Trivial t1;  // Default-initialized via bitwise zeroing if possible
    Trivial t2 = t1;  // Compiler may optimize to a simple memory copy
    return 0;
}
